use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct SgConfig {
    #[serde(default)]
    pub rule_dirs: Vec<String>,
    #[serde(default)]
    pub util_dirs: Vec<String>,
    #[serde(default)]
    pub test_configs: Vec<TestConfig>,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct TestConfig {
    pub test_dir: String,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct RuleConfig {
    pub id: String,
    pub language: Option<String>,
    pub rule: RuleObject,
    pub constraints: Option<HashMap<String, RuleObject>>,
    pub utils: Option<HashMap<String, RuleObject>>,
    pub transform: Option<HashMap<String, TransformObject>>,
    pub fix: Option<FixConfig>,
    pub message: Option<String>,
    pub severity: Option<String>,
    pub note: Option<String>,
    pub metadata: Option<serde_json::Value>,
    pub files: Option<Vec<String>>,
    pub ignores: Option<Vec<String>>,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(untagged)]
pub enum FixConfig {
    Str(String),
    Obj(FixObject),
}

impl FixConfig {
    pub fn get_template(&self) -> &str {
        match self {
            FixConfig::Str(s) => s.as_str(),
            FixConfig::Obj(o) => o.template.as_str(),
        }
    }
}

#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct FixObject {
    pub template: String,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(untagged)]
pub enum RuleObject {
    PatternStr(String),
    Obj(RuleDetail),
}

#[derive(Debug, Clone, Deserialize, Serialize, Default)]
#[serde(rename_all = "camelCase")]
pub struct RuleDetail {
    pub pattern: Option<PatternKind>,
    pub kind: Option<String>,
    pub regex: Option<String>,
    pub selector: Option<String>,
    pub all: Option<Vec<RuleObject>>,
    pub any: Option<Vec<RuleObject>>,
    pub not: Option<Box<RuleObject>>,
    pub has: Option<Box<RuleObject>>,
    pub inside: Option<Box<RuleObject>>,
    pub precedes: Option<Box<RuleObject>>,
    pub follows: Option<Box<RuleObject>>,
    pub matches: Option<String>,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(untagged)]
pub enum PatternKind {
    Str(String),
    Obj(PatternObj),
}

impl PatternKind {
    pub fn get_pattern_str(&self) -> &str {
        match self {
            PatternKind::Str(s) => s.as_str(),
            PatternKind::Obj(o) => o.context.as_deref().unwrap_or(o.selector.as_deref().unwrap_or("")),
        }
    }
}

#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct PatternObj {
    pub context: Option<String>,
    pub selector: Option<String>,
    pub strictness: Option<String>,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct TransformObject {
    pub substring: Option<SubstringTransform>,
    pub replace: Option<ReplaceTransform>,
    pub convert: Option<ConvertTransform>,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct SubstringTransform {
    pub source: String,
    pub start_char: Option<isize>,
    pub end_char: Option<isize>,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ReplaceTransform {
    pub source: String,
    pub replace: String,
    pub by: String,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ConvertTransform {
    pub source: String,
    pub to_case: String,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct TestCaseFile {
    pub id: String,
    #[serde(default)]
    pub valid: Vec<serde_json::Value>,
    #[serde(default)]
    pub invalid: Vec<serde_json::Value>,
}

impl SgConfig {
    pub fn load<P: AsRef<Path>>(path: P) -> anyhow::Result<Self> {
        let content = std::fs::read_to_string(path)?;
        let config: SgConfig = serde_yaml::from_str(&content)?;
        Ok(config)
    }
}

pub fn find_sgconfig<P: AsRef<Path>>(config_path: Option<&str>, current_dir: P) -> Option<(PathBuf, SgConfig)> {
    let target = config_path.unwrap_or("sgconfig.yml");
    let target_path = Path::new(target);
    if target_path.is_absolute() {
        if let Ok(cfg) = SgConfig::load(target_path) {
            return Some((target_path.to_path_buf(), cfg));
        }
    } else {
        let mut cur = current_dir.as_ref().to_path_buf();
        loop {
            let candidate = cur.join(target);
            if candidate.exists() {
                if let Ok(cfg) = SgConfig::load(&candidate) {
                    return Some((candidate, cfg));
                }
            }
            if !cur.pop() {
                break;
            }
        }
    }
    None
}
