        column: byte_offset - last_line_start,
    }
}

pub fn compute_lines_and_char_count(code: &str, start_byte: usize, end_byte: usize) -> (String, CharCount) {
    let start_pos = compute_position(code, start_byte);
    let end_pos = compute_position(code, end_byte);

    let line_starts: Vec<usize> = std::iter::once(0)
        .chain(code.match_indices('\n').map(|(i, _)| i + 1))
        .collect();

    let start_line_byte = line_starts.get(start_pos.line).cloned().unwrap_or(0);
    let end_line_byte = if end_pos.line + 1 < line_starts.len() {
        line_starts[end_pos.line + 1].saturating_sub(1)
    } else {
        code.len()
    };

    let lines = code[start_line_byte..end_line_byte].to_string();
    let leading = start_pos.column;
    let trailing = if end_pos.line + 1 < line_starts.len() {
        line_starts[end_pos.line + 1].saturating_sub(1).saturating_sub(end_byte)
    } else {
        code.len().saturating_sub(end_byte)
    };

    (lines, CharCount { leading, trailing })
}

pub fn search_pattern(
    code: &str,
    file_path: &str,
    lang: Language,
    pattern: &str,
) -> Vec<MatchResult> {
    let pat_tokens = tokenize_pattern(pattern);
    let code_tokens = tokenize_code(code);
    let mut results = Vec::new();

    if pat_tokens.is_empty() || code_tokens.is_empty() {
        return results;
    }

    // Attempt matching starting at every code token position
    for i in 0..code_tokens.len() {
        let mut single_vars: HashMap<String, MetaVarMatch> = HashMap::new();
        let mut multi_vars: HashMap<String, Vec<MetaVarMatch>> = HashMap::new();

        if let Some(end_idx) = match_tokens(&pat_tokens, 0, &code_tokens, i, code, &mut single_vars, &mut multi_vars) {
            let start_byte = code_tokens[i].start;
            let end_byte = code_tokens[end_idx - 1].end;
            let start_pos = compute_position(code, start_byte);
            let end_pos = compute_position(code, end_byte);

            let (lines, char_count) = compute_lines_and_char_count(code, start_byte, end_byte);

            results.push(MatchResult {
                text: code[start_byte..end_byte].to_string(),
                range: MatchRange {
                    byte_offset: ByteOffset { start: start_byte, end: end_byte },
                    start: start_pos,
                    end: end_pos,
                },
                file: file_path.to_string(),
                lines,
                char_count,
                language: lang.name().to_string(),
                meta_variables: MetaVariables {
                    single: single_vars,
                    multi: multi_vars,
                    transformed: HashMap::new(),
                },
                rule_id: None,
                severity: None,
                note: None,
                message: None,
                labels: None,
                metadata: None,
                replacement: None,
            });
        }
    }

    results
}

fn match_tokens(
    pat_tokens: &[Token],
    pat_idx: usize,
    code_tokens: &[CodeToken],
    code_idx: usize,
    code: &str,
    single_vars: &mut HashMap<String, MetaVarMatch>,
    multi_vars: &mut HashMap<String, Vec<MetaVarMatch>>,
) -> Option<usize> {
    if pat_idx == pat_tokens.len() {
        return Some(code_idx);
    }

    let p_tok = &pat_tokens[pat_idx];

    match p_tok {
        Token::Literal(lit) => {
            if code_idx >= code_tokens.len() {
                return None;
            }
            if &code_tokens[code_idx].text == lit {
                match_tokens(pat_tokens, pat_idx + 1, code_tokens, code_idx + 1, code, single_vars, multi_vars)
            } else {
                None
            }
        }
        Token::SingleMetaVar(name) => {
            if code_idx >= code_tokens.len() {
                return None;
            }
            let c_tok = &code_tokens[code_idx];

            let start_byte = c_tok.start;
            let end_byte = c_tok.end;
            let text = c_tok.text.clone();

            if name != "_" && !name.starts_with('_') {
                if let Some(prev) = single_vars.get(name) {
                    if prev.text != text {
                        return None;
                    }
                }
            }

            let start_pos = compute_position(code, start_byte);
            let end_pos = compute_position(code, end_byte);
            let mv = MetaVarMatch {
                text: text.clone(),
                range: MatchRange {
                    byte_offset: ByteOffset { start: start_byte, end: end_byte },
                    start: start_pos,
                    end: end_pos,
                },
            };

            let old_val = single_vars.insert(name.clone(), mv);
            let res = match_tokens(pat_tokens, pat_idx + 1, code_tokens, code_idx + 1, code, single_vars, multi_vars);
            if res.is_none() {
                if let Some(old) = old_val {
                    single_vars.insert(name.clone(), old);
                } else {
                    single_vars.remove(name);
                }
            }
            res
        }
        Token::MultiMetaVar(name) => {
            // MultiMetaVar can match 0 or more tokens
            // Try matching 0, 1, 2, ... tokens until match succeeds
            let next_pat = pat_idx + 1;
            for count in 0..=(code_tokens.len() - code_idx) {
                let matched_tokens = &code_tokens[code_idx..code_idx + count];
                let items: Vec<MetaVarMatch> = matched_tokens
                    .iter()
                    .map(|tok| MetaVarMatch {
                        text: tok.text.clone(),
                        range: MatchRange {
                            byte_offset: ByteOffset { start: tok.start, end: tok.end },
                            start: compute_position(code, tok.start),
                            end: compute_position(code, tok.end),
                        },
                    })
                    .collect();

                let old_val = multi_vars.insert(name.clone(), items);
                if let Some(res) = match_tokens(pat_tokens, next_pat, code_tokens, code_idx + count, code, single_vars, multi_vars) {
                    return Some(res);
                }
                if let Some(old) = old_val {
                    multi_vars.insert(name.clone(), old);
                } else {
                    multi_vars.remove(name);
                }
            }
            None
        }
    }
}

pub fn apply_rewrite(
    rewrite_template: &str,
    meta_vars: &MetaVariables,
) -> String {
    let mut res = rewrite_template.to_string();

    // Replace single variables
    for (name, mv) in &meta_vars.single {
        let key1 = format!("${}", name);
        res = res.replace(&key1, &mv.text);
    }

    // Replace transformed variables
    for (name, mv) in &meta_vars.transformed {
        let key1 = format!("${}", name);
        res = res.replace(&key1, &mv.text);
    }

    // Replace multi variables
    for (name, list) in &meta_vars.multi {
        let key1 = format!("$$${}", name);
        let joined = list.iter().map(|item| item.text.as_str()).collect::<Vec<_>>().join(" ");
        res = res.replace(&key1, &joined);
    }

    res
}
