pub fn apply_transforms(
    transforms: &HashMap<String, TransformObject>,
    meta_vars: &mut MetaVariables,
) {
    for (key, trans) in transforms {
        if let Some(conv) = &trans.convert {
            let src_text = resolve_source(&conv.source, meta_vars);
            let converted = match conv.to_case.as_str() {
                "camelCase" => to_camel_case(&src_text),
                "pascalCase" => to_pascal_case(&src_text),
