                _ => src_text,
            };
            meta_vars.transformed.insert(
                key.clone(),
                MetaVarMatch {
                    text: converted,
                    range: MatchRange {
                        byte_offset: ByteOffset { start: 0, end: 0 },
                        start: Position { line: 0, column: 0 },
