            let src_text = resolve_source(&sub.source, meta_vars);
            let start = sub.start_char.unwrap_or(0).max(0) as usize;
            let end = sub.end_char.map(|e| e.max(0) as usize).unwrap_or(src_text.len()).min(src_text.len());
            let sliced = if start < src_text.len() && start <= end {
                src_text[start..end].to_string()
            } else {
                String::new()
            };
            meta_vars.transformed.insert(
                key.clone(),
                MetaVarMatch {
                    text: sliced,
                    range: MatchRange {
                        byte_offset: ByteOffset { start: 0, end: 0 },
                        start: Position { line: 0, column: 0 },
                        end: Position { line: 0, column: 0 },
                    },
                },
            );
        } else if let Some(rep) = &trans.replace {
            let src_text = resolve_source(&rep.source, meta_vars);
            let replaced = if let Ok(re) = Regex::new(&rep.replace) {
                re.replace_all(&src_text, rep.by.as_str()).to_string()
            } else {
                src_text.replace(&rep.replace, &rep.by)
            };
            meta_vars.transformed.insert(
                key.clone(),
                MetaVarMatch {
                    text: replaced,
                    range: MatchRange {
                        byte_offset: ByteOffset { start: 0, end: 0 },
                        start: Position { line: 0, column: 0 },
                        end: Position { line: 0, column: 0 },
                    },
                },
            );
        }
    }
}

fn resolve_source(source: &str, meta_vars: &MetaVariables) -> String {
    let var_name = source.trim_start_matches('$');
    if let Some(mv) = meta_vars.single.get(var_name) {
        return mv.text.clone();
    }
    if let Some(mv) = meta_vars.transformed.get(var_name) {
        return mv.text.clone();
    }
    source.to_string()
}

fn to_camel_case(s: &str) -> String {
    let pascal = to_pascal_case(s);
    if let Some(c) = pascal.chars().next() {
        let mut chars = pascal.chars();
        chars.next();
        format!("{}{}", c.to_lowercase(), chars.as_str())
    } else {
        pascal
    }
}

fn to_pascal_case(s: &str) -> String {
    let mut res = String::new();
    let clean = s.trim_matches('"').trim_matches('\'');
    let mut capitalize = true;
    for c in clean.chars() {
        if c == '_' || c == '-' || c.is_whitespace() {
            capitalize = true;
        } else if capitalize {
            res.push(c.to_ascii_uppercase());
            capitalize = false;
        } else {
            res.push(c);
        }
    }
    res
}

fn to_snake_case(s: &str) -> String {
    let mut res = String::new();
    let clean = s.trim_matches('"').trim_matches('\'');
    for (i, c) in clean.chars().enumerate() {
        if c.is_uppercase() {
            if i > 0 {
                res.push('_');
            }
            res.push(c.to_ascii_lowercase());
        } else {
            res.push(c);
        }
    }
    res
}

fn to_kebab_case(s: &str) -> String {
    to_snake_case(s).replace('_', "-")
}
