use crate::matcher::*;
use std::collections::HashMap;

pub enum HeadingMode {
    Auto,
    Always,
    Never,
}

impl HeadingMode {
    pub fn parse(s: &str) -> Self {
        match s.to_lowercase().as_str() {
            "always" => HeadingMode::Always,
            "never" => HeadingMode::Never,
            _ => HeadingMode::Auto,
        }
    }

    pub fn should_heading(&self) -> bool {
        match self {
            HeadingMode::Always => true,
            HeadingMode::Never => false,
            HeadingMode::Auto => {
                use is_terminal_polyfill::IsTerminal;
                std::io::stdout().is_terminal()
            }
        }
    }
}

pub fn print_matches_plain(
    matches: &[MatchResult],
    heading_mode: &HeadingMode,
    context_before: usize,
    context_after: usize,
    code_map: &HashMap<String, String>,
) {
    if matches.is_empty() {
        return;
    }

    let show_heading = heading_mode.should_heading();

    // Group matches by file
    let mut by_file: HashMap<String, Vec<&MatchResult>> = HashMap::new();
    let mut file_order = Vec::new();
    for m in matches {
        if !by_file.contains_key(&m.file) {
            file_order.push(m.file.clone());
        }
        by_file.entry(m.file.clone()).or_default().push(m);
    }

    for file in file_order {
        let file_matches = &by_file[&file];
        let code = code_map.get(&file).cloned().unwrap_or_default();
        let code_lines: Vec<&str> = code.lines().collect();

        if show_heading {
            println!("{}", file);
            for m in file_matches {
                let start_line = m.range.start.line;
                let line_str = if start_line < code_lines.len() {
                    code_lines[start_line]
                } else {
                    &m.lines
                };
                println!("{}│{}", start_line + 1, line_str);
            }
            println!();
        } else {
            let mut last_printed_line: Option<usize> = None;
            for (idx, m) in file_matches.iter().enumerate() {
                let start_line = m.range.start.line;
                let end_line = m.range.end.line;

                let print_start = start_line.saturating_sub(context_before);
                let print_end = (end_line + context_after).min(code_lines.len().saturating_sub(1));

                if idx > 0 && context_before + context_after > 0 {
                    if let Some(last) = last_printed_line {
                        if print_start > last + 1 {
                            println!("--");
                        }
                    }
                }

                for line_idx in print_start..=print_end {
                    let line_text = if line_idx < code_lines.len() {
                        code_lines[line_idx]
                    } else {
                        ""
                    };
                    println!("{}:{}:{}", file, line_idx + 1, line_text);
                    last_printed_line = Some(line_idx);
                }
            }
        }
    }
}

pub fn print_matches_json(matches: &[MatchResult], style: &str) {
    match style {
        "stream" => {
            for m in matches {
                if let Ok(json) = serde_json::to_string(m) {
                    println!("{}", json);
                }
            }
        }
        "compact" => {
            if let Ok(json) = serde_json::to_string(matches) {
                println!("{}", json);
            }
        }
        _ => {
            // pretty
            if let Ok(json) = serde_json::to_string_pretty(matches) {
                println!("{}", json);
            }
        }
    }
}

pub fn print_diffs(
    file_path: &str,
    orig_code: &str,
    new_code: &str,
) {
    if orig_code == new_code {
        return;
    }

    println!("{}", file_path);
    let orig_lines: Vec<&str> = orig_code.lines().collect();
    let new_lines: Vec<&str> = new_code.lines().collect();

    println!("@@ -0,{} +0,{} @@", orig_lines.len(), new_lines.len());

    let max_lines = orig_lines.len().max(new_lines.len());
    for i in 0..max_lines {
        let orig_l = orig_lines.get(i).cloned().unwrap_or("");
        let new_l = new_lines.get(i).cloned().unwrap_or("");

        let line_num = i + 1;
        if orig_l == new_l {
            println!("{:>1} {:>1}│ {}", line_num, line_num, orig_l);
        } else {
            if !orig_l.is_empty() {
                println!("{:>1}  │-{}", line_num, orig_l);
            }
            if !new_l.is_empty() {
                println!("  {:>1}│+{}", line_num, new_l);
            }
        }
    }
}

pub fn print_scan_rich(m: &MatchResult) {
    let sev = m.severity.as_deref().unwrap_or("warning");
