    }

    println!("{}", file_path);
    let orig_lines: Vec<&str> = orig_code.lines().collect();
    let new_lines: Vec<&str> = new_code.lines().collect();

    println!("@@ -0,{} +0,{} @@", orig_lines.len(), new_lines.len());

    let max_lines = orig_lines.len().max(new_lines.len());
    for i in 0..max_lines {
