{"command":"cat << 'EOF' > src/commands/run.rs
use crate::cli::RunArgs;
use crate::lang::Language;
use crate::matcher::*;
use crate::printer::*;
use ignore::WalkBuilder;
use std::collections::HashMap;
use std::io::{self, Read};
use std::path::Path;

pub fn execute_run(args: &RunArgs) -> anyhow::Result<()> {
    let pattern = match &args.pattern {
        Some(p) => p.as_str(),
        None => {
            eprintln!("error: the following required arguments were not provided:");
            eprintln!("  --pattern <PATTERN>");
            eprintln!("\nUsage: executable run --pattern <PATTERN> [PATHS]...\n");
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    };

    if args.stdin {
        let lang_str = match &args.lang {
            Some(l) => l,
            None => {
                eprintln!("Error: Language must be specified for code from StdIn.");
                eprintln!("Help: Please use `--lang` to specify the code language.");
                eprintln!("See also: https://ast-grep.github.io/guide/tooling-overview.html#parse-code-from-stdin");
                std::process::exit(3);
            }
        };

        let lang = match Language::from_str(lang_str) {
            Some(l) => l,
            None => {
                eprintln!("error: invalid value '{}' for '--lang <LANG>': {} is not supported!", lang_str, lang_str);
                std::process::exit(2);
            }
        };

        let mut stdin_code = String::new();
        io::stdin().read_to_string(&mut stdin_code)?;

        let matches = search_pattern(&stdin_code, "STDIN", lang, pattern);

        if matches.is_empty() {
            std::process::exit(1);
        }

        if args.files_with_matches {
            println!("STDIN");
            std::process::exit(0);
        }

        if let Some(json_style) = &args.json {
            let style = json_style.as_deref().unwrap_or("pretty");
            print_matches_json(&matches, style);
            std::process::exit(0);
        }

        if let Some(rewrite_fmt) = &args.rewrite {
            let mut new_code = stdin_code.clone();
            for m in matches.iter().rev() {
                let rw = apply_rewrite(rewrite_fmt, &m.meta_variables);
                let start = m.range.byte_offset.start;
                let end = m.range.byte_offset.end;
                new_code.replace_range(start..end, &rw);
            }
            if args.update_all {
                print!("{}", new_code);
            } else {
                print_diffs("STDIN", &stdin_code, &new_code);
            }
            std::process::exit(0);
        }

        let heading_mode = HeadingMode::parse(&args.heading);
        let mut code_map = HashMap::new();
        code_map.insert("STDIN".to_string(), stdin_code);
        let ctx_before = if args.context > 0 { args.context } else { args.before };
        let ctx_after = if args.context > 0 { args.context } else { args.after };

        print_matches_plain(&matches, &heading_mode, ctx_before, ctx_after, &code_map);
        std::process::exit(0);
    }

    // Path walking
    let paths = if args.paths.is_empty() {
        vec![".".to_string()]
    } else {
        args.paths.clone()
    };

    let explicit_lang = args.lang.as_deref().and_then(Language::from_str);

    let mut builder = WalkBuilder::new(&paths[0]);
    for p in paths.iter().skip(1) {
        builder.add(p);
    }

    if args.follow {
        builder.follow_links(true);
    }

    let mut all_matches = Vec::new();
    let mut code_map = HashMap::new();
    let mut matched_files = Vec::new();
    let mut modified_file_count = 0;

    for result in builder.build() {
        let entry = match result {
            Ok(e) => e,
            Err(_) => continue,
        };

        let path = entry.path();
        if !path.is_file() {
            continue;
        }

        let lang = match explicit_lang {
            Some(l) => l,
            None => match Language::from_path(path) {
                Some(l) => l,
                None => continue,
            },
        };

        let file_path_str = path.to_string_lossy().trim_start_matches("./").to_string();
        let code = match std::fs::read_to_string(path) {
            Ok(c) => c,
            Err(_) => continue,
        };

        let mut matches = search_pattern(&code, &file_path_str, lang, pattern);
        if !matches.is_empty() {
            matched_files.push(file_path_str.clone());

