{"command":"cat << 'EOF' > src/commands/scan.rs
use crate::cli::ScanArgs;
use crate::config::*;
use crate::lang::Language;
use crate::matcher::*;
use crate::printer::*;
use ignore::WalkBuilder;
use regex::Regex;
use std::collections::HashMap;
use std::path::Path;

pub fn execute_scan(args: &ScanArgs) -> anyhow::Result<()> {
    let mut rules: Vec<RuleConfig> = Vec::new();

    if let Some(rule_file) = &args.rule {
        let content = match std::fs::read_to_string(rule_file) {
            Ok(c) => c,
            Err(_) => {
                eprintln!("Error: Cannot parse rule {}", rule_file);
                eprintln!("Help: The file is not a valid ast-grep rule. Please refer to doc and fix the error.");
                eprintln!("See also: https://ast-grep.github.io/guide/rule-config.html");
                std::process::exit(8);
            }
        };
        let rule_cfg: RuleConfig = match serde_yaml::from_str(&content) {
            Ok(r) => r,
            Err(e) => {
                eprintln!("Error: Cannot parse rule {}", rule_file);
                eprintln!("Help: The file is not a valid ast-grep rule. Please refer to doc and fix the error.");
                eprintln!("See also: https://ast-grep.github.io/guide/rule-config.html\n");
                eprintln!("✖ Caused by\n╰▻ Fail to parse yaml as Rule.\n╰▻ {}", e);
                std::process::exit(8);
            }
        };
        rules.push(rule_cfg);
    } else if let Some(inline_text) = &args.inline_rules {
        for doc in inline_text.split("\n---") {
            let trimmed = doc.trim();
            if trimmed.is_empty() {
                continue;
            }
            let rule_cfg: RuleConfig = match serde_yaml::from_str(trimmed) {
                Ok(r) => r,
                Err(e) => {
                    eprintln!("Error: Cannot parse rule INLINE_RULES");
                    eprintln!("Help: The file is not a valid ast-grep rule. Please refer to doc and fix the error.");
                    eprintln!("See also: https://ast-grep.github.io/guide/rule-config.html\n");
                    eprintln!("✖ Caused by\n╰▻ Fail to parse yaml as RuleConfig\n╰▻ {}", e);
                    std::process::exit(8);
                }
            };
            rules.push(rule_cfg);
        }
    } else {
        // Load sgconfig.yml
        let current_dir = std::env::current_dir()?;
        let (config_path, sg_config) = match find_sgconfig(args.config.as_deref(), &current_dir) {
            Some(pair) => pair,
            None => {
                eprintln!("Error: No ast-grep project configuration is found.");
                eprintln!("Help: You need to create an ast-grep project for this command. Try `sg new` to create one.");
                eprintln!("See also: https://ast-grep.github.io/guide/scan-project.html");
                std::process::exit(3);
            }
        };

        let root_dir = config_path.parent().unwrap_or(Path::new("."));
        for rdir in &sg_config.rule_dirs {
            let rule_dir_path = root_dir.join(rdir);
            if rule_dir_path.exists() {
                for entry in walkdir::WalkDir::new(rule_dir_path) {
                    if let Ok(e) = entry {
                        if e.path().is_file() {
                            let ext = e.path().extension().and_then(|s| s.to_str()).unwrap_or("");
                            if ext == "yml" || ext == "yaml" {
                                if let Ok(content) = std::fs::read_to_string(e.path()) {
                                    if let Ok(rc) = serde_yaml::from_str::<RuleConfig>(&content) {
                                        rules.push(rc);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    // Filter rules
    if let Some(filter_pat) = &args.filter {
        if let Ok(re) = Regex::new(filter_pat) {
            rules.retain(|r| re.is_match(&r.id));
        }
    }

    // Inspect summary
    if args.inspect == "summary" || args.inspect == "entity" {
        let cur_dir = std::env::current_dir().unwrap_or_default();
        eprintln!("sg: summary|project: isProject=true,projectDir={}", cur_dir.display());
    }

    // Apply severity overrides
    let mut overrides: HashMap<String, String> = HashMap::new();
    if let Some(errs) = &args.error {
        if errs.is_empty() {
            for r in &rules { overrides.insert(r.id.clone(), "error".to_string()); }
        } else {
            for id in errs { overrides.insert(id.clone(), "error".to_string()); }
        }
    }
    if let Some(warns) = &args.warning {
        if warns.is_empty() {
            for r in &rules { overrides.insert(r.id.clone(), "warning".to_string()); }
        } else {
            for id in warns { overrides.insert(id.clone(), "warning".to_string()); }
        }
    }
    if let Some(infos) = &args.info {
        if infos.is_empty() {
            for r in &rules { overrides.insert(r.id.clone(), "info".to_string()); }
        } else {
            for id in infos { overrides.insert(id.clone(), "info".to_string()); }
        }
    }
    if let Some(hints) = &args.hint {
        if hints.is_empty() {
            for r in &rules { overrides.insert(r.id.clone(), "hint".to_string()); }
        } else {
            for id in hints { overrides.insert(id.clone(), "hint".to_string()); }
        }
    }
    if let Some(offs) = &args.off {
        if offs.is_empty() {
            for r in &rules { overrides.insert(r.id.clone(), "off".to_string()); }
        } else {
            for id in offs { overrides.insert(id.clone(), "off".to_string()); }
        }
    }

    let paths = if args.paths.is_empty() {
        vec![".".to_string()]
    } else {
        args.paths.clone()
    };

    let mut builder = WalkBuilder::new(&paths[0]);
    for p in paths.iter().skip(1) {
        builder.add(p);
    }
    if args.follow {
        builder.follow_links(true);
    }

    let mut all_results = Vec::new();
    let mut total_scanned_files = 0;
    let mut error_count = 0;

    for entry_res in builder.build() {
        let entry = match entry_res {
            Ok(e) => e,
            Err(_) => continue,
        };
        let path = entry.path();
        if !path.is_file() {
            continue;
        }

        let file_path_str = path.to_string_lossy().trim_start_matches("./").to_string();
        let code = match std::fs::read_to_string(path) {
            Ok(c) => c,
            Err(_) => continue,
        };

        total_scanned_files += 1;

        for rule in &rules {
            let effective_sev = overrides.get(&rule.id).cloned().unwrap_or_else(|| {
                rule.severity.clone().unwrap_or_else(|| "help".to_string())
            });

            if effective_sev == "off" {
                continue;
            }

            let rule_lang = rule.language.as_deref().and_then(Language::from_str);

            if let Some(rl) = rule_lang {
                if let Some(file_lang) = Language::from_path(path) {
                    if rl != file_lang {
                        continue;
                    }
                } else {
                    continue;
                }
            }

            let pattern_str = match &rule.rule {
                RuleObject::PatternStr(s) => s.as_str(),
                RuleObject::Obj(o) => o.pattern.as_ref().map(|p| p.get_pattern_str()).unwrap_or(""),
            };

            let lang = rule_lang.or_else(|| Language::from_path(path)).unwrap_or(Language::JavaScript);

            let mut matches = search_pattern(&code, &file_path_str, lang, pattern_str);

            for mut m in matches.drain(..) {
                if let Some(trans) = &rule.transform {
                    apply_transforms(trans, &mut m.meta_variables);
                }

                m.rule_id = Some(rule.id.clone());
                m.severity = Some(effective_sev.clone());
                m.note = Some(rule.note.clone());
                m.message = Some(rule.message.clone().unwrap_or_default());
                m.labels = Some(vec![Label {
                    text: m.text.clone(),
                    range: m.range.clone(),
                    style: "primary".to_string(),
                }]);

                if args.include_metadata {
                    m.metadata = rule.metadata.clone();
                }

                if let Some(fix_cfg) = &rule.fix {
                    let rewrite_tmpl = fix_cfg.get_template();
                    let rw = apply_rewrite(rewrite_tmpl, &m.meta_variables);
                    m.replacement = Some(rw);
                }

                if effective_sev == "error" {
                    error_count += 1;
                }

                all_results.push(m);

                if let Some(max_res) = args.max_results {
                    if all_results.len() >= max_res {
                        break;
                    }
                }
            }

            if let Some(max_res) = args.max_results {
                if all_results.len() >= max_res {
                    break;
                }
            }
        }

        if let Some(max_res) = args.max_results {
            if all_results.len() >= max_res {
                break;
            }
        }
    }

    if args.inspect == "summary" || args.inspect == "entity" {
        eprintln!("sg: summary|file: scannedFileCount={},skippedFileCount=0", total_scanned_files);
        eprintln!("sg: summary|rule: effectiveRuleCount={},skippedRuleCount=0", rules.len());
    }

    // Format results
    if let Some(fmt) = &args.format {
        match fmt.as_str() {
            "github" => {
                for m in &all_results {
                    print_scan_github(m);
                }
            }
            "sarif" => {
                print_scan_sarif(&all_results);
            }
            _ => {}
        }
    } else if let Some(json_style) = &args.json {
        let style = json_style.as_deref().unwrap_or("pretty");
        print_matches_json(&all_results, style);
    } else {
        for m in &all_results {
            if let Some(rw) = &m.replacement {
                let mut new_code = m.lines.clone();
                new_code = new_code.replace(&m.text, rw);
                print_diffs(&m.file, &m.lines, &new_code);
            }
            match args.report_style.as_str() {
                "short" => print_scan_short(m),
                "medium" => print_scan_short(m),
                _ => print_scan_rich(m),
            }
        }
