                m.note = Some(rule.note.clone());
                m.message = Some(rule.message.clone().unwrap_or_default());
                m.labels = Some(vec![Label {
                    text: m.text.clone(),
                    range: m.range.clone(),
                    style: "primary".to_string(),
                }]);

