        }
    } else if let Some(json_style) = &args.json {
        let style = json_style.as_deref().unwrap_or("pretty");
        print_matches_json(&all_results, style);
    } else {
        for m in &all_results {
            if let Some(rw) = &m.replacement {
                let mut new_code = m.lines.clone();
