                "medium" => print_scan_short(m),
                _ => print_scan_rich(m),
            }
        }
    }

    if error_count > 0 {
        eprintln!("Error: {} error(s) found in code.", error_count);
        eprintln!("Help: Scan succeeded and found error level diagnostics in the codebase.\n");
        std::process::exit(1);
    }

    std::process::exit(0);
}
