{"command":"cat << 'EOF' > src/commands/new_cmd.rs
use crate::cli::NewArgs;
use crate::config::*;
use crate::lang::Language;
use std::path::Path;

pub fn execute_new(args: &NewArgs) -> anyhow::Result<()> {
    let sub = args.command.as_deref().unwrap_or("project");

    match sub {
        "project" => create_project(args),
        "rule" => create_rule(args),
        "test" => create_test(args),
        "util" => create_util(args),
        _ => {
            eprintln!("unrecognized subcommand '{}'", sub);
            std::process::exit(2);
        }
    }
}

fn create_project(_args: &NewArgs) -> anyhow::Result<()> {
    println!("Creating a new ast-grep project...");

    let sg_config_content = "ruleDirs:\n- rules\ntestConfigs:\n- testDir: rule-tests\nutilDirs:\n- utils\n";
    let _ = std::fs::write("sgconfig.yml", sg_config_content);
    let _ = std::fs::create_dir_all("rules");
    let _ = std::fs::create_dir_all("rule-tests");
    let _ = std::fs::create_dir_all("utils");

    println!("Your new ast-grep project has been created!");
    std::process::exit(0);
}

fn create_rule(args: &NewArgs) -> anyhow::Result<()> {
    let name = match &args.name {
        Some(n) => n,
        None => "my-rule",
    };

    let lang_str = args.lang.as_deref().unwrap_or("TypeScript");
    let lang = Language::from_str(lang_str).map(|l| l.name()).unwrap_or("TypeScript");

    let current_dir = std::env::current_dir()?;
    let (config_path, sg_config) = match find_sgconfig(args.config.as_deref(), &current_dir) {
        Some(pair) => pair,
        None => {
            eprintln!("Error: No ast-grep project configuration is found.");
            std::process::exit(3);
        }
    };

    let root_dir = config_path.parent().unwrap_or(Path::new("."));
    let rule_dir = sg_config.rule_dirs.first().map(|s| s.as_str()).unwrap_or("rules");
    let rule_file_path = root_dir.join(rule_dir).join(format!("{}.yml", name));

    if rule_file_path.exists() {
        eprintln!("Error: File `{}` already exists.", rule_file_path.display());
        eprintln!("Help: The item you want to create already exists. Try editing the existing file or create a new one with a different name?\n");
        std::process::exit(17);
    }

    let rule_content = format!(
        "# yaml-language-server: $schema=https://raw.githubusercontent.com/ast-grep/ast-grep/main/schemas/rule.json\n\nid: {}\nmessage: Add your rule message here....\nseverity: error # error, warning, info, hint\nlanguage: {}\nrule:\n  pattern: Your Rule Pattern here...\n# utils: Extract repeated rule as local utility here.\n# note: Add detailed explanation for the rule.\n",
        name, lang
    );

    let _ = std::fs::create_dir_all(rule_file_path.parent().unwrap());
    std::fs::write(&rule_file_path, rule_content)?;
    println!("Created rules at {}", rule_file_path.canonicalize()?.display());

    // Also create test file if possible
    let test_dir = sg_config.test_configs.first().map(|t| t.test_dir.as_str()).unwrap_or("rule-tests");
    let test_file_path = root_dir.join(test_dir).join(format!("{}-test.yml", name));
    if !test_file_path.exists() {
        let test_content = format!("id: {}\nvalid:\n- \"valid code\"\ninvalid:\n- \"invalid code\"\n", name);
        let _ = std::fs::create_dir_all(test_file_path.parent().unwrap());
        std::fs::write(&test_file_path, test_content)?;
    }

    std::process::exit(0);
}

fn create_test(args: &NewArgs) -> anyhow::Result<()> {
    let name = match &args.name {
        Some(n) => n,
        None => "my-rule",
