{"command":"cat << 'EOF' > src/main.rs
mod cli;
mod config;
mod commands;
mod lang;
mod matcher;
mod printer;

use cli::*;
use commands::completions_cmd::execute_completions;
use commands::lsp_cmd::execute_lsp;
use commands::new_cmd::execute_new;
use commands::run::execute_run;
use commands::scan::execute_scan;
use commands::test_cmd::execute_test;

fn main() -> anyhow::Result<()> {
    let matches = build_cli().get_matches();

    match matches.subcommand() {
        Some(("run", sub_m)) => {
            let run_args = parse_run_args(sub_m);
            execute_run(&run_args)
        }
        Some(("scan", sub_m)) => {
            let scan_args = parse_scan_args(sub_m);
            execute_scan(&scan_args)
        }
        Some(("test", sub_m)) => {
            let test_args = parse_test_args(sub_m);
            execute_test(&test_args)
        }
        Some(("new", sub_m)) => {
            let new_args = parse_new_args(sub_m);
            execute_new(&new_args)
        }
        Some(("lsp", sub_m)) => {
            let cfg = sub_m.get_one::<String>("config").map(|s| s.as_str());
            execute_lsp(cfg)
        }
        Some(("completions", sub_m)) => {
            let shell = sub_m.get_one::<String>("shell").map(|s| s.as_str());
            execute_completions(shell)
        }
        _ => {
            // Check if top-level run options like pattern were passed
            if matches.contains_id("pattern") && matches.get_one::<String>("pattern").is_some() {
                let run_args = parse_run_args(&matches);
                execute_run(&run_args)
            } else {
                let mut cmd = build_cli();
                cmd.print_help()?;
                println!();
                std::process::exit(2);
            }
        }
    }
}

fn parse_run_args(m: &clap::ArgMatches) -> RunArgs {
    RunArgs {
        pattern: m.get_one::<String>("pattern").cloned(),
        selector: m.get_one::<String>("selector").cloned(),
        rewrite: m.get_one::<String>("rewrite").cloned(),
        lang: m.get_one::<String>("lang").cloned(),
