use commands::test_cmd::execute_test;

fn main() -> anyhow::Result<()> {
    let matches = build_cli().get_matches();

    match matches.subcommand() {
        Some(("run", sub_m)) => {
            let run_args = parse_run_args(sub_m);
            execute_run(&run_args)
        }
        Some(("scan", sub_m)) => {
            let scan_args = parse_scan_args(sub_m);
            execute_scan(&scan_args)
        }
        Some(("test", sub_m)) => {
